struct MsgFrameBuilder {
  typedef MsgFrame Table;
  flatbuffers::FlatBufferBuilder &fbb_;
  flatbuffers::uoffset_t start_;
  void add_timestamps(uint64_t timestamps) {
    fbb_.AddElement<uint64_t>(MsgFrame::VT_TIMESTAMPS, timestamps, 0);
  }
  void add_msg_type(TGMsg::MsgUnion msg_type) {
    fbb_.AddElement<uint8_t>(MsgFrame::VT_MSG_TYPE, static_cast<uint8_t>(msg_type), 0);
  }
  void add_msg(flatbuffers::Offset<void> msg) {
    fbb_.AddOffset(MsgFrame::VT_MSG, msg);
  }
  explicit MsgFrameBuilder(flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  flatbuffers::Offset<MsgFrame> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = flatbuffers::Offset<MsgFrame>(end);
    return o;
  }
};

inline flatbuffers::Offset<MsgFrame> CreateMsgFrame(
    flatbuffers::FlatBufferBuilder &_fbb,
    uint64_t timestamps = 0,
    TGMsg::MsgUnion msg_type = TGMsg::MsgUnion_NONE,
    flatbuffers::Offset<void> msg = 0) {
  MsgFrameBuilder builder_(_fbb);
  builder_.add_timestamps(timestamps);
  builder_.add_msg(msg);
  builder_.add_msg_type(msg_type);
  return builder_.Finish();
}

flatbuffers::Offset<MsgFrame> CreateMsgFrame(flatbuffers::FlatBufferBuilder &_fbb, const MsgFrameT *_o, const flatbuffers::rehasher_function_t *_rehasher = nullptr);

inline MsgFrameT *MsgFrame::UnPack(const flatbuffers::resolver_function_t *_resolver) const {
  auto _o = std::unique_ptr<MsgFrameT>(new MsgFrameT());
  UnPackTo(_o.get(), _resolver);
  return _o.release();
}

inline void MsgFrame::UnPackTo(MsgFrameT *_o, const flatbuffers::resolver_function_t *_resolver) const {
  (void)_o;
  (void)_resolver;
  { auto _e = timestamps(); _o->timestamps = _e; }
  { auto _e = msg_type(); _o->msg.type = _e; }
  { auto _e = msg(); if (_e) _o->msg.value = TGMsg::MsgUnionUnion::UnPack(_e, msg_type(), _resolver); }
}

inline flatbuffers::Offset<MsgFrame> MsgFrame::Pack(flatbuffers::FlatBufferBuilder &_fbb, const MsgFrameT* _o, const flatbuffers::rehasher_function_t *_rehasher) {
  return CreateMsgFrame(_fbb, _o, _rehasher);
}

inline flatbuffers::Offset<MsgFrame> CreateMsgFrame(flatbuffers::FlatBufferBuilder &_fbb, const MsgFrameT *_o, const flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { flatbuffers::FlatBufferBuilder *__fbb; const MsgFrameT* __o; const flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _timestamps = _o->timestamps;
  auto _msg_type = _o->msg.type;
  auto _msg = _o->msg.Pack(_fbb);
  return TGMsg::CreateMsgFrame(
      _fbb,
      _timestamps,
      _msg_type,
      _msg);
}

